  const f=await ledgerFixture(t),args={evidence_bundle:f.bundle,reviewed_obligations:[f.obligation('owned')],manifest:{bindings:[f.binding('owned')],contradictions:[]}},ready=(await f.c.call('build_reconstruction_obligation_ledger',args)).normalized_result;assert.equal(ready.status,'ready');assert.equal(ready.summary.verified,1);
